import random

def controller(obs, memory) -> int:
    """
    Improved staged controller with anti-stuck measures.

    Stages:
      1: explore to find key
      2: go to key
      3: pick up key (handled inside stage 2/explicit)
      4: explore/find locked door (matching key color)
      5: go to locked door
      6: unlock the locked door
      7: drop the key on an empty cell in front
      8: go through the door / search ball
      9: pick up the ball

    Actions:
      0 turn_left, 1 turn_right, 2 forward, 3 pickup, 4 drop, 5 toggle, 6 done
    """
    # Allowed standard modules used: random
    # Object codes
    OBJ_UNSEEN = 0
    OBJ_EMPTY = 1
    OBJ_WALL = 2
    OBJ_FLOOR = 3
    OBJ_DOOR = 4
    OBJ_KEY = 5
    OBJ_BALL = 6
    OBJ_BOX = 7
    OBJ_GOAL = 8
    OBJ_LAVA = 9
    OBJ_AGENT = 10

    image = obs['image']

    # Initialize persistent memory fields
    if 'stage' not in memory:
        memory['stage'] = 1
        memory['key_color'] = None
        memory['target_rel'] = None
        # action history for stuck detection
        memory['last_action'] = None
        memory['repeat'] = 0
        memory['hist'] = []

    def in_bounds(i, j):
        return 0 <= i < 7 and 0 <= j < 7

    def rel_to_ij(dx, dy):
        i = 3 + dx
        j = 6 + dy
        return i, j

    def ij_to_rel(i, j):
        dx = i - 3
        dy = j - 6
        return dx, dy

    def get_cell_by_rel(dx, dy):
        i, j = rel_to_ij(dx, dy)
        if not in_bounds(i, j):
            return (OBJ_UNSEEN, 0, 0)
        return tuple(image[i][j])

    def get_cell_front():
        return get_cell_by_rel(0, -1)

    def carrying():
        return image[3][6][0]  # object code carried; 1 = nothing

    def can_forward(cell):
        obj, col, state = cell
        if obj in (OBJ_EMPTY, OBJ_FLOOR, OBJ_GOAL):
            return True
        if obj == OBJ_DOOR and state == 0:
            return True
        return False

    def find_all_objects(obj_codes=None, state_eq=None, color_eq=None):
        res = []
        for i in range(7):
            for j in range(7):
                o, c, s = image[i][j]
                if o == OBJ_UNSEEN:
                    continue
                if obj_codes is not None and o not in obj_codes:
                    continue
                if state_eq is not None and s != state_eq:
                    continue
                if color_eq is not None and c != color_eq:
                    continue
                dx, dy = ij_to_rel(i, j)
                res.append((dx, dy, o, c, s))
        res.sort(key=lambda x: (abs(x[0]) + abs(x[1]), abs(x[1]), abs(x[0])))
        return res

    def find_nearest(obj_codes=None, state_eq=None, color_eq=None):
        lst = find_all_objects(obj_codes=obj_codes, state_eq=state_eq, color_eq=color_eq)
        return lst[0] if lst else None

    def orient_towards(dx, dy):
        # Reactive steering toward a relative target (dx,dy).
        # Prefer to bring object into front column (dx==0 and dy<0) then forward.
        if dx == 0 and dy < 0:
            front = get_cell_front()
            if can_forward(front):
                return 2  # forward
            if front[0] == OBJ_DOOR and front[2] == 1:
                return 5  # open closed door
            if front[0] == OBJ_DOOR and front[2] == 2:
                # locked door behavior handled by stage logic
                return 1  # rotate to find alternate route
            # rotate to look
            return random.choice([0, 1])
        if dx < 0:
            return 0  # turn_left
        if dx > 0:
            return 1  # turn_right
        # dx == 0 and dy >= 0 (target behind or same cell) -> prefer turning left to avoid repeated right
        return 0

    # Anti-stuck wrapper: update history and override repetitive turning
    def choose_action(action):
        last = memory.get('last_action')
        repeat = memory.get('repeat', 0)
        hist = memory.get('hist', [])
        # Update tentative repeat count
        if action == last:
            repeat = repeat + 1
        else:
            repeat = 1
        # Anti-stuck overrides:
        front_cell = get_cell_front()
        # If we've been repeating a rotation many times, try the opposite rotation or try a different action.
        if repeat >= 4 and action in (0, 1):
            # If front is a wall, try the other turn direction
            if front_cell[0] == OBJ_WALL:
                alt = 0 if action == 1 else 1
                # occasionally try forward if accidentally became movable
                if can_forward(front_cell) and random.random() < 0.3:
                    action = 2
                else:
                    action = alt
                # reset repeat metric so we don't immediately flip back
                repeat = 1
            else:
                # If we've been turning a lot but front is not a wall, try forward if possible
                if can_forward(front_cell):
                    action = 2
                    repeat = 1
                else:
                    # try toggling door if it's a door in front
                    if front_cell[0] == OBJ_DOOR:
                        action = 5
                        repeat = 1
                    else:
                        # try the opposite turn
                        action = 0 if action == 1 else 1
                        repeat = 1
        # If completely stuck (very large repeat), pick a random alternative to escape
        if repeat >= 8:
            choices = [0, 1, 2]
            # prefer forward if possible
            if can_forward(front_cell):
                action = 2
            else:
                action = random.choice(choices)
            repeat = 1

        # Record action history and return
        memory['last_action'] = action
        memory['repeat'] = repeat
        hist.append(action)
        if len(hist) > 12:
            hist.pop(0)
        memory['hist'] = hist
        return action

    # Read current front cell and state
    front = get_cell_front()

    # Quick state transitions and sanity checks
    stage = memory['stage']
    # Ensure we don't lose progress if we carry key
    if carrying() == OBJ_KEY and stage < 4:
        memory['stage'] = 4
        stage = 4
    if carrying() != OBJ_KEY and stage >= 7 and stage < 8:
        # If we dropped the key as intended, proceed to search ball
        memory['stage'] = 8
        stage = 8
    # If we somehow lost the key and were past initial stages, restart search
    if carrying() != OBJ_KEY and stage > 3 and stage < 8:
        memory['stage'] = 1
        stage = 1

    # If carrying key but no color stored, try to determine key color from visible keys (we might still see it)
    if carrying() == OBJ_KEY and memory.get('key_color') is None:
        kseen = find_nearest(obj_codes=[OBJ_KEY])
        if kseen:
            memory['key_color'] = kseen[3]

    # If we see the ball while not carrying the key (or after drop), prefer going to ball
    ball_seen = find_nearest(obj_codes=[OBJ_BALL])
    if ball_seen and carrying() != OBJ_KEY and stage < 9:
        memory['target_rel'] = (ball_seen[0], ball_seen[1])
        # If ball is directly in front, pick it
        if ball_seen[0] == 0 and ball_seen[1] == -1 and front[0] == OBJ_BALL:
            memory['stage'] = 9
            return choose_action(3)

    # Stage-by-stage logic
    # Stage 1: Explore to find the key
    if stage == 1:
        key_seen = find_nearest(obj_codes=[OBJ_KEY])
        if key_seen:
            dx, dy, o, c, s = key_seen
            memory['key_color'] = c
            memory['target_rel'] = (dx, dy)
            memory['stage'] = 2
            return choose_action(orient_towards(dx, dy))
        # Open closed door in front if present
        if front[0] == OBJ_DOOR and front[2] == 1:
            return choose_action(5)
        # Move forward if possible, else rotate (alternate turns to avoid repeating same turn)
        if can_forward(front):
            return choose_action(2)
        # pick alternating left/right to avoid stuck rotation pattern
        return choose_action(random.choice([0, 1]))

    # Stage 2: Go to key
    if stage == 2:
        if carrying() == OBJ_KEY:
            memory['stage'] = 4
            return choose_action(random.choice([0, 1]))  # harmless rotate to update
        key_seen = find_nearest(obj_codes=[OBJ_KEY])
        if not key_seen:
            memory['stage'] = 1
            memory['target_rel'] = None
            return choose_action(random.choice([0, 1]))
        dx, dy, o, c, s = key_seen
        memory['target_rel'] = (dx, dy)
        # If key is directly in front, pick it up
        if dx == 0 and dy == -1 and front[0] == OBJ_KEY:
            return choose_action(3)
        # Handle doors blocking the way
        if front[0] == OBJ_DOOR and front[2] == 1:
            return choose_action(5)
        if front[0] == OBJ_DOOR and front[2] == 2:
            # locked door blocks; try turning to find another route
            return choose_action(random.choice([0, 1]))
        return choose_action(orient_towards(dx, dy))

    # Stage 3: (not used explicitly) fallback to stage 2
    if stage == 3:
        memory['stage'] = 2
        return choose_action(1)

    # Stage 4: Find locked door matching key color
    if stage == 4:
        kcol = memory.get('key_color')
        if carrying() == OBJ_KEY and kcol is None:
            key_seen = find_nearest(obj_codes=[OBJ_KEY])
            if key_seen:
                memory['key_color'] = key_seen[3]
                kcol = key_seen[3]
        lock_seen = find_nearest(obj_codes=[OBJ_DOOR], state_eq=2, color_eq=kcol)
        if lock_seen:
            dx, dy, _, _, _ = lock_seen
            memory['target_rel'] = (dx, dy)
            memory['stage'] = 5
            return choose_action(orient_towards(dx, dy))
        # Explore: open closed doors encountered
        if front[0] == OBJ_DOOR and front[2] == 1:
            return choose_action(5)
        if can_forward(front):
            return choose_action(2)
        return choose_action(random.choice([0, 1]))

    # Stage 5: Go to the locked door
    if stage == 5:
        kcol = memory.get('key_color')
        lock_seen = find_nearest(obj_codes=[OBJ_DOOR], state_eq=2, color_eq=kcol)
        if not lock_seen:
            memory['stage'] = 4
            return choose_action(random.choice([0, 1]))
        dx, dy, o, c, s = lock_seen
        memory['target_rel'] = (dx, dy)
        # If door is directly in front and locked, try unlocking if we have correct key
        if dx == 0 and dy == -1:
            if front[0] == OBJ_DOOR and front[2] == 2:
                if carrying() == OBJ_KEY and memory.get('key_color') == front[1]:
                    memory['stage'] = 6
                    return choose_action(5)
                else:
                    memory['stage'] = 4
                    return choose_action(random.choice([0, 1]))
            if can_forward(front):
                return choose_action(2)
        if front[0] == OBJ_DOOR and front[2] == 1:
            return choose_action(5)
        return choose_action(orient_towards(dx, dy))

    # Stage 6: Unlock the locked door and step in
    if stage == 6:
        # If still locked, try again if we have correct key
        if front[0] == OBJ_DOOR and front[2] == 2:
            if carrying() == OBJ_KEY and memory.get('key_color') == front[1]:
                return choose_action(5)
            memory['stage'] = 4
            return choose_action(random.choice([0, 1]))
        # If door is now passable, step forward to be inside and then drop in next stage
        if can_forward(front):
            memory['stage'] = 7
            return choose_action(2)
        # Otherwise rotate to get proper alignment
        return choose_action(random.choice([0, 1]))

    # Stage 7: Drop the key on an empty cell in front (empty can be OBJ_EMPTY or OBJ_FLOOR/OBJ_GOAL)
    if stage == 7:
        if carrying() != OBJ_KEY:
            memory['stage'] = 8
            return choose_action(random.choice([0, 1]))
        # Consider a cell droppable if it's empty/floor/goal (we relax strictness)
        if front[0] in (OBJ_EMPTY, OBJ_FLOOR, OBJ_GOAL):
            memory['stage'] = 8
            return choose_action(4)
        # If forward passable but not droppable (rare), move forward to find droppable cell
        if can_forward(front):
            return choose_action(2)
        # If front is a closed door, open it
        if front[0] == OBJ_DOOR and front[2] == 1:
            return choose_action(5)
        # Otherwise rotate to find an empty spot
        return choose_action(random.choice([0, 1]))

    # Stage 8: Search for and go to the ball (after dropping key)
    if stage == 8:
        ball = find_nearest(obj_codes=[OBJ_BALL])
        if ball:
            dx, dy, o, c, s = ball
            memory['target_rel'] = (dx, dy)
            if dx == 0 and dy == -1 and front[0] == OBJ_BALL:
                if carrying() == OBJ_KEY:
                    memory['stage'] = 7
                    return choose_action(random.choice([0, 1]))
                memory['stage'] = 9
                return choose_action(3)
            return choose_action(orient_towards(dx, dy))
        # Otherwise explore
        if front[0] == OBJ_DOOR and front[2] == 1:
            return choose_action(5)
        if can_forward(front):
            return choose_action(2)
        return choose_action(random.choice([0, 1]))

    # Stage 9: Pick up the ball
    if stage == 9:
        if front[0] == OBJ_BALL and carrying() != OBJ_KEY:
            return choose_action(3)
        ball = find_nearest(obj_codes=[OBJ_BALL])
        if ball:
            dx, dy, o, c, s = ball
            return choose_action(orient_towards(dx, dy))
        if can_forward(front):
            return choose_action(2)
        return choose_action(random.choice([0, 1]))

    # Default fallback: explore and try to open doors
    if front[0] == OBJ_DOOR and front[2] == 1:
        return choose_action(5)
    if can_forward(front):
        return choose_action(2)
    return choose_action(random.choice([0, 1]))
